DO $verify181$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 331 AND law_year = 2025 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[181] القرار 331/2025 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 6 THEN RAISE EXCEPTION '[181] عدد المواد % بدل 6', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2026-02-08';
  IF v_v <> 6 THEN RAISE EXCEPTION '[181] عدد النسخ % بدل 6', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%األ%' OR body LIKE '%اإل%' OR body LIKE '%اآل%' OR body LIKE '%خالل%' OR body LIKE '%الوقائع المصریة%' OR body LIKE '%الوقائع املصرية%' OR body LIKE '%الوقائع المصرية -%' OR body LIKE '%فبراير سنة 2026%' OR body LIKE '%املصرية%' OR body LIKE '%صورة إ%' OR body LIKE '%ل تداول%' OR body LIKE '% ً%' OR body LIKE '%���%' OR body LIKE '%( )%' OR body LIKE '%٪%' OR body LIKE '%٢٠%' OR body LIKE '%ال يقل%' OR body LIKE '%- 1%' OR body LIKE '%نطاق التطبيق%' OR body LIKE '%قسط التأمين%' OR body LIKE '%طاب %' OR body LIKE '%ثاث%' OR body LIKE '%تحميات%' OR body LIKE '%الاطاع%' OR body LIKE '%٫%' OR body LIKE '%تحميالت%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[181] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظ%' AND body LIKE '%ه المنعقدة بتاريخ 2025/12/24 ؛' AND body LIKE '%رقم 10 لسنة 2009 بتنظيم الرقابة%' AND body LIKE '%رقم 155 لسنة 2024 والقرارات%' AND body LIKE '%رقم 1583 لسنة 2019 بإنشاء صندوق التأمين الحكومى لرعاية طلاب مدارس مصر ؛%' AND body LIKE '%قرار وزير التربية والتعليم رقم 224 لسنة 2015 بشأن نظام التأمين على الطلبة ضد الحوادث ؛%' AND body LIKE '%وعلى الطلب المقدم من الصندوق بشأن تعديل شروط وأسعار التأمين لديه ؛%' AND body LIKE '%وعلى موافقة مجلس إدارة الصندوق ؛%' AND body LIKE '%بتاريخ 2025/12/24 ؛') THEN RAISE EXCEPTION '[181] ديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تسرى أحكام هذا القرار فى شأن شروط وأسعار عملي%' AND body LIKE '%قم 1583 لسنة 2019 المشار إليه.' AND body LIKE '%لرعاية طلاب مدارس مصر.%' AND body LIKE '%ويتمتع طلاب المدارس التابعة لوزارة التربية والتعليم والتعليم الفنى%' AND body LIKE '%رقم 1583 لسنة 2019 المشار إليه.') THEN RAISE EXCEPTION '[181] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'يكون مقابل الاشتراك السنوى بالصندوق بواقع مبل%' AND body LIKE '%، تسدد مع المصروفات الدراسية.' AND body LIKE '%مبلغ 10.60 جنيه مصرى (عشرة جنيهات وستون قرشًا) عن كل طالب ، تسدد مع المصروفات الدراسية.') THEN RAISE EXCEPTION '[181] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'أولاً - التعويض فى حالة الوفاة والعجز الكلى ا%' AND body LIKE '%ولمرة واحدة خلال فترة الدراسة.' AND body LIKE '%ثلاثون ألف جنيه مصرى فى حالة وفاة الطالب%' AND body LIKE '%3- ألا يكون الحادث ناتجًا عن انتحار أو إصابة متعمدة.%' AND body LIKE '%ثلاث سنوات من تاريخ الوفاة أو وقوع الحادث%' AND body LIKE '%خمسة عشر ألف جنيه مصرى%' AND body LIKE '%ثالثًا - التعويض فى حالة العجز الجزئى المستديم الناتج عن حادث :%' AND body LIKE '%رابعًا - الإعانات الاجتماعية :%' AND body LIKE '%ألفان وخمسمائة جنيه مصرى عن كل مرة وبحد أقصى ثلاث مرات%' AND body LIKE '%بحد أقصى ثلاثون ألف جنيه مصري.%' AND body LIKE '%ألف وسبعمائة وخمسون جنيهًا مصريًا للطالب ذوى الإعاقة بمدارس التربية الخاصة%' AND body LIKE '%5- حالات الأجهزة التعويضية :%' AND body LIKE '%ولمرة واحدة خلال فترة الدراسة.') THEN RAISE EXCEPTION '[181] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'يلتزم الصندوق بمراجعة قيمة الاشتراك السنوى ،%' AND body LIKE '%موافاة الهيئة بها فور إعدادها.' AND body LIKE '%وموافاة الهيئة بها فور إعدادها.') THEN RAISE EXCEPTION '[181] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار فى الوقائع المصرية وعلى الموق%' AND body LIKE '%د. محمد فريد صالح' AND body LIKE '%ويعمل به اعتبارًا من العام الدراسى 2025 - 2026 ، ويلغى كل حكم يخالف أحكامه.%' AND body LIKE '%د. محمد فريد صالح') THEN RAISE EXCEPTION '[181] المادة 5 غير سليم'; END IF;
  IF v_len <> 5251 THEN RAISE EXCEPTION '[181] إجمالى طول المواد % بدل 5251', v_len; END IF;
  RAISE NOTICE '[181] القرار 331/2025: 6 مواد و6 نسخ، إجمالى % حرف', v_len;
END
$verify181$;

COMMIT;
